(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.DonghaengFinal=factory()})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const STATION=[37.60192,127.0414554],COVERAGE={south:37.580,west:127.020,north:37.611,east:127.058};
function inCoverage(ll){return Array.isArray(ll)&&ll[0]>=COVERAGE.south&&ll[0]<=COVERAGE.north&&ll[1]>=COVERAGE.west&&ll[1]<=COVERAGE.east}
function stopCandidates(features,E){return features.filter(f=>{const p=f.properties||{},t=p.osm_tags||{};return ['bench','seating'].includes(f.kind||p.kind)&&f.geometry?.type==='Point'&&!p.apartment_name&&p.context!=='apartment_polygon'&&!['private','customers','residents','no'].includes(p.access||t.access)&&!['provider_triangulated_bench_estimate','address_reference_not_individual_bench','public_space_parcel_reference'].includes(p.coordinate_role)&&inCoverage([f.geometry.coordinates[1],f.geometry.coordinates[0]])}).map(f=>{const p=f.properties;return {id:f.id||p.id,ll:[f.geometry.coordinates[1],f.geometry.coordinates[0]],name:p.name||(f.kind==='seating'?'등록 의자 시설':'OSM 등록 벤치'),kind:f.kind||p.kind,sourceUrl:p.source_url,coordinateRole:p.coordinate_role||'mapped_point',notice:p.notice||'현장 상태·진입 연결 미확인',approximate:p.coordinate_role!=='mapped_point'&&Boolean(p.coordinate_role),accuracy:p.coordinate_accuracy_m||null}}).filter(f=>E.distance(f.ll,STATION)<2600)}
function restCandidates(features,E){const benches=stopCandidates(features,E);const shelters=features.filter(f=>{const p=f.properties||{},t=p.osm_tags||{};return f.kind==='shelter'&&f.geometry?.type==='Point'&&!p.apartment_name&&p.context!=='apartment_polygon'&&!['private','residents','customers','no'].includes(p.access||t.access)&&!/특정계층|회원이용|경로당/.test(p.facility_type||'')&&inCoverage([f.geometry.coordinates[1],f.geometry.coordinates[0]])&&E.distance([f.geometry.coordinates[1],f.geometry.coordinates[0]],STATION)<2600}).map(f=>{const p=f.properties;return {id:f.id,ll:[f.geometry.coordinates[1],f.geometry.coordinates[0]],kind:'shelter',name:p.name||'등록 쉼터',sourceUrl:p.source_url,notice:p.notice||'현장 상태·계절 운영 미확인',coordinateRole:p.coordinate_role||'mapped_point',approximate:p.coordinate_role!=='mapped_point'&&Boolean(p.coordinate_role),openingHours:p.opening_hours||p.osm_tags?.opening_hours,officialFields:p.official_fields,operation:p.operational_status,evidenceNotice:p.rest_evidence_note}});return [...benches,...shelters]}
function dashboard(features,E){const counts={};for(const f of features)counts[f.kind]=(counts[f.kind]||0)+1;const local=features.filter(f=>['bench','seating'].includes(f.kind)&&E.distance([f.geometry.type==='Point'?f.geometry.coordinates[1]:f.properties.latitude||0,f.geometry.type==='Point'?f.geometry.coordinates[0]:f.properties.longitude||0],STATION)<=800);return {total:features.length,counts,records:features.filter(f=>!['complex','apartment'].includes(f.kind)).length,localRest:local.length}}
function placeOptions(features,places,E){const out=new Map();for(const p of places)out.set('osm-place:'+p.id,{...p});for(const f of features){const p=f.properties;if(!p.name||!['bench','seating','shelter','elevator'].includes(f.kind)||f.geometry?.type!=='Point')continue;const ll=[f.geometry.coordinates[1],f.geometry.coordinates[0]];if(inCoverage(ll)&&E.distance(ll,STATION)<=1800)out.set('facility:'+f.id,{id:'facility:'+f.id,name:p.name,ll,type:f.kind,sourceUrl:p.source_url,approximate:p.coordinate_role!=='mapped_point'})}return [...out.values()].filter(p=>inCoverage(p.ll)).sort((a,b)=>E.distance(a.ll,STATION)-E.distance(b.ll,STATION))}
const SCENARIOS={short:{text:'가장 짧은 거리로 가고 싶어요.',label:'빠른 이동'},rest:{text:'무릎이 아파 계단과 오르막은 피하고, 중간에 벤치에 앉아서 쉬고 싶어요.',label:'쉬어 가는 이동'},wheelchair:{text:'휠체어를 이용해요. 계단은 이용할 수 없어요.',label:'계단을 피하는 이동'}};
return {STATION,COVERAGE,inCoverage,stopCandidates,restCandidates,dashboard,placeOptions,SCENARIOS};
});
